    if not (3 <= n <= 5):
        return False
    if len(r) != n or len(c) != n:
        return False
    return all(ch in "ABC" for ch in r) and all(ch in "ABC" for ch in c)


def _solve(n, R, Cs):
    # Backtracking row by row. Each row places A, B, C in three distinct columns.
    # Column constraints: each letter at most once per column (total 3N letters
    # with N rows forces exactly one of each per column/row).
    # Top-most constraint: the first letter placed in a column must equal Cs[col].
    # Left-most constraint: the smallest-index column in a row must hold R[i].
    letters = "ABC"
    grid = [['.'] * n for _ in range(n)]
    cnt = [[0, 0, 0] for _ in range(n)]
    used = [False] * n

    def rec(i):
        if i == n:
            return True
        for cols in permutations(range(n), 3):
            # cols[k] is the column for letters[k]
            ok = True
            for k in range(3):
                if cnt[cols[k]][k] != 0:
                    ok = False
                    break
                if not used[cols[k]] and letters[k] != Cs[cols[k]]:
                    ok = False
                    break
            if not ok:
                continue
            leftmost = min(cols)
            if letters[cols.index(leftmost)] != R[i]:
                continue
            # apply
            changed = []
            for k in range(3):
                c = cols[k]
                changed.append((c, used[c]))
                cnt[c][k] += 1
                used[c] = True
                grid[i][c] = letters[k]
            if rec(i + 1):
                return True
            # undo
            for k in range(3):
                c = cols[k]
                cnt[c][k] -= 1
                grid[i][c] = '.'
            for c, u in changed:
                used[c] = u
        return False

    if rec(0):
        return ["".join(row) for row in grid]
    return None


def ref(inp):
    t = inp.split()
    n = int(t[0])
    R, Cs = t[1], t[2]
    res = _solve(n, R, Cs)
    if res is None:
        return "No"
    return "Yes\n" + "\n".join(res)


def same(inp, expected, got):
    t = inp.split()
    n = int(t[0])
    R, Cs = t[1], t[2]
    g = got.split()
    exp_yes = expected.split()[0] == "Yes"
    if not g:
        return False
    if not exp_yes:
        return g == ["No"]
    if g[0] != "Yes":
        return False
    rows = g[1:]
    if len(rows) != n:
        return False
    if any(len(row) != n for row in rows):
        return False
    if any(ch not in ".ABC" for row in rows for ch in row):
        return False
    for row in rows:
        if sorted(ch for ch in row if ch != '.') != ['A', 'B', 'C']:
            return False
    for j in range(n):
        col = [rows[i][j] for i in range(n)]
        if sorted(ch for ch in col if ch != '.') != ['A', 'B', 'C']:
            return False
    for i in range(n):
        filled = [(j, rows[i][j]) for j in range(n) if rows[i][j] != '.']
        if filled[0][1] != R[i]:
            return False
    for j in range(n):
        filled = [(i, rows[i][j]) for i in range(n) if rows[i][j] != '.']
        if filled[0][1] != Cs[j]:
            return False
    return True
